// Revalida a entrada do chat no servidor.
const b = $json.body || {};
const protocolo = String(b.protocolo ?? '').trim().toUpperCase();
const email = String(b.email ?? '').trim().toLowerCase();
const mensagem = String(b.mensagem ?? '').trim();
const sessionId = String(b.sessionId ?? '').trim();

const erros = {};
if (!/^DV-\d{8}-[A-Z0-9]{4}$/.test(protocolo)) erros.protocolo = 'O protocolo deve seguir o formato DV-AAAAMMDD-XXXX.';
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erros.email = 'E-mail em formato inválido.';
if (mensagem.length < 1 || mensagem.length > 1000) erros.mensagem = 'A mensagem deve ter entre 1 e 1.000 caracteres.';
if (!/^[A-Za-z0-9-]{8,64}$/.test(sessionId)) erros.sessionId = 'Sessão inválida. Recarregue a página.';

return {
  json: {
    valido: Object.keys(erros).length === 0,
    erros,
    mensagem_erro: Object.values(erros).join(' '),
    protocolo, email, mensagem, sessionId,
  },
};

// Só libera a conversa se o protocolo existir E o e-mail for o mesmo da abertura.
// A IA nunca acessa a planilha: ela recebe apenas os dados desta dúvida.
const ent = $('Validar Entrada do Chat').first().json;
const linhas = $input.all().map((i) => i.json);
const linha = linhas.find((r) =>
  String(r.protocolo ?? '').trim().toUpperCase() === ent.protocolo &&
  String(r.email ?? '').trim().toLowerCase() === ent.email
);
if (!linha) return [{ json: { encontrado: false } }];

// Chaves viram parênteses para não quebrar o template da IA.
const t = (v, padrao = '') => {
  const s = String(v ?? '').trim();
  return (s || padrao).replace(/[{}]/g, (c) => (c === '{' ? '(' : ')'));
};

const contexto = [
  'DADOS DA DÚVIDA (use somente estes dados para falar do andamento):',
  `- Protocolo: ${t(linha.protocolo)}`,
  `- Aberta em: ${t(linha.data_abertura)}`,
  `- Primeiro nome do aluno: ${t(String(linha.nome ?? '').split(' ')[0], 'aluno')}`,
  `- Dúvida original: ${t(linha.duvida)}`,
  `- Categoria: ${t(linha.categoria)} | Urgência: ${t(linha.urgencia)}`,
  `- Resposta automática enviada: ${t(linha.resposta_ia, 'nenhuma')}`,
  `- Status: ${t(linha.status, 'Em revisão')}`,
  `- Responsável: ${t(linha.responsavel, 'ainda não definido')}`,
  `- Última atualização da equipe: ${t(linha.ultima_atualizacao, 'nenhuma atualização registrada')}`,
  `- Informações já enviadas pelo aluno: ${t(linha.informacoes_aluno, 'nenhuma')}`,
  '',
  '<mensagem_do_aluno>',
  t(ent.mensagem),
  '</mensagem_do_aluno>',
].join('\n');

return [{
  json: {
    encontrado: true,
    protocolo: ent.protocolo,
    sessionId: ent.sessionId,
    status: String(linha.status ?? '').trim() || 'Em revisão',
    informacoes_aluno: String(linha.informacoes_aluno ?? '').trim(),
    contexto,
  },
}];

