// Normaliza a saída do agente e prepara o registro de informação nova.
const ctx = $('Verificar Identidade').first().json;
const out = $json.output || {};
const resposta = (typeof out.resposta === 'string' && out.resposta.trim())
  ? out.resposta.replace(/\\+"/g, '"').trim().slice(0, 1500)
  : 'Não consegui formular uma resposta agora. Pode reformular a pergunta?';
const resumo = String(out.resumo_informacao ?? '').replace(/\s+/g, ' ').trim().slice(0, 500);
const registrar = out.informacao_nova === true && resumo.length > 0;

const agora = DateTime.now().setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy HH:mm');
const novaLinha = `[${agora}] ${resumo}`;

return [{
  json: {
    protocolo: ctx.protocolo,
    status: ctx.status,
    resposta,
    registrar,
    informacoes_aluno: ctx.informacoes_aluno ? `${ctx.informacoes_aluno}\n${novaLinha}` : novaLinha,
    data_ultima_interacao: agora,
  },
}];
